old=pd.read_csv(R/'input/cookchem_molecular_retention_preprocessed.csv');led=pd.read_csv(R/'recovery_v0_1_0_2026_11_10/source_to_target_ledger.csv');new=pd.read_csv(R/'dataset_expansion_1000/batch_021/updated_master_dataset.csv')
keys=set(new.original_record_id.dropna().astype(str)); oldidx=old.set_index('Record_ID'); newidx=new.dropna(subset=['original_record_id']).set_index('original_record_id')
def ndoi(x):return str(x).lower().strip().replace('https://doi.org/','')
rows=[]
for _,r in led.iterrows():
    match=bool(r.retention_final_matches_stored_ratio); mapped=str(r.record_id) in keys; status=''
    if not match: status='arithmetic_inconsistent' if pd.notna(r.calculated_concentration_ratio_percent) else 'not_arithmetically_verifiable'
    elif mapped: status='arithmetic_and_source_verified'
    elif r.evidence_status=='DOI_MISMATCH':status='arithmetic_consistent_source_conflict'
    elif r.evidence_status=='TARGET_FORMULA_UNRESOLVED':status='arithmetic_consistent_pairing_ambiguous'
    elif str(r.initial_unit)!=str(r.final_unit):status='arithmetic_consistent_measurement_basis_unverified'
    else:status='arithmetic_consistent_source_metadata_missing'
    reason={'arithmetic_and_source_verified':'Exact original record ID, DOI, and canonical molecule map to Batch021 primary-source evidence.','arithmetic_consistent_source_metadata_missing':'No contradiction found, but no locally preserved primary-source locator that unambiguously verifies the pair.','arithmetic_consistent_measurement_basis_unverified':'Stored raw/cooked units differ; no valid conversion/evidence retained.','arithmetic_consistent_pairing_ambiguous':'Preserved audit marks target formula or raw/cooked pairing unresolved.','arithmetic_consistent_source_conflict':'Preserved DOI metadata contradicts the stored experiment.','arithmetic_inconsistent':'Stored Retention_Final differs from stored calculated concentration ratio.','not_arithmetically_verifiable':'Raw/cooked comparison unavailable in preserved audit.'}[status]
    finalid=''; calc=np.nan; loc=''; basis='';
    if mapped:
        q=newidx.loc[str(r.record_id)];finalid=q.observation_id;calc=q.target_value_percent;loc=q.source_locator;basis=q.measurement_basis
    rows.append(dict(record_id=r.record_id,doi=r.doi,compound=r.compound,canonical_molecular_id=r.canonical_molecular_id,food_matrix=r.food_matrix,cooking_method=r.cooking_method,retention_final=r.retention_final,stored_calculated_ratio=r.calculated_concentration_ratio_percent,arithmetic_match=match,initial_concentration=r.initial_concentration,final_concentration=r.final_concentration,initial_unit=r.initial_unit,final_unit=r.final_unit,previous_evidence_status=r.evidence_status,recovery_classification=status,recovery_reason=reason,mapped_final_observation_id=finalid,verified_ratio_from_primary=calc,evidence_locator=loc,measurement_basis=basis))
a=pd.DataFrame(rows); m=a[a.arithmetic_match];m.to_csv(O/'989_arithmetic_matching_observations_audit.csv',index=False);m[m.recovery_classification!='arithmetic_and_source_verified'].to_csv(O/'651_previously_excluded_matching_observations_audit.csv',index=False);a[a.recovery_classification=='arithmetic_inconsistent'].to_csv(O/'81_discrepant_observations_audit.csv',index=False);a[a.recovery_classification=='not_arithmetically_verifiable'].to_csv(O/'54_unverifiable_observations_audit.csv',index=False)
v=m[m.recovery_classification=='arithmetic_and_source_verified'].copy(); sub=old[old.Record_ID.isin(v.record_id)].copy(); sub['verified_concentration_ratio_percent']=sub.Record_ID.map(v.set_index('record_id').verified_ratio_from_primary);sub.to_csv(O/'expanded_verified_original_subset.csv',index=False)
a.groupby('recovery_classification').size().rename('observations').reset_index().to_csv(O/'recovery_and_exclusion_summary.csv',index=False);a[['record_id','doi','mapped_final_observation_id','evidence_locator','measurement_basis','recovery_classification']].to_csv(O/'source_recovery_manifest.csv',index=False);a[['record_id','retention_final','stored_calculated_ratio','verified_ratio_from_primary','arithmetic_match','recovery_classification']].to_csv(O/'target_calculation_verification.csv',index=False)
# Exact historical feature schema on the recovered historical subset; target comes from primary mapping.
num=['Temperature_C','Cooking_Time_min','Pressure_kPa','Microwave_Power_W','Sample_Weight_g','Initial_Concentration','Replicates_n','RDKit_Molecular_Weight','RDKit_LogP','RDKit_TPSA','RDKit_HBond_Donors','RDKit_HBond_Acceptors','RDKit_Rotatable_Bonds','RDKit_Aromatic_Rings','RDKit_Hydroxyl_Groups','RDKit_Heavy_Atom_Count'];cat=['Assay_Method_Standardized','Compound_Class_Standardized','Cooking_Medium_Standardized','Cooking_Method_Standardized','Food_Name_Standardized','Initial_Unit_Standardized','Oil_Type_Standardized'];x=sub[num+cat].copy()
for c in num:x[c]=pd.to_numeric(x[c],errors='coerce')
x['temperature_time_interaction']=x.Temperature_C*x.Cooking_Time_min;x['log_cooking_time']=np.log1p(x.Cooking_Time_min.clip(lower=0));x['log_initial_concentration']=np.log1p(x.Initial_Concentration.clip(lower=0));x['logp_temperature_interaction']=x.RDKit_LogP*x.Temperature_C;x['tpsa_time_interaction']=x.RDKit_TPSA*x.Cooking_Time_min
nums=list(x.select_dtypes(include=np.number));cats=[c for c in x if c not in nums];pre=ColumnTransformer([('n',Pipeline([('i',SimpleImputer(strategy='median')),('s',StandardScaler())]),nums),('c',Pipeline([('i',SimpleImputer(strategy='constant',fill_value='Missing')),('o',OneHotEncoder(handle_unknown='ignore',sparse_output=False))]),cats)]);y=sub.verified_concentration_ratio_percent.astype(float);g=sub.Canonical_Molecular_ID.astype(str);met=[]
for f,(tr,te) in enumerate(GroupKFold(5).split(x,y,g),1):
 p=Pipeline([('p',pre),('m',XGBRegressor(n_estimators=450,max_depth=3,learning_rate=.03,min_child_weight=3,subsample=.8,colsample_bytree=.8,reg_lambda=5,objective='reg:squarederror',random_state=42,n_jobs=1,tree_method='hist',verbosity=0))]);p.fit(x.iloc[tr],np.log1p(y.iloc[tr]));z=np.expm1(np.clip(p.predict(x.iloc[te]),-20,20));td=set(sub.iloc[te].DOI.map(ndoi));trd=set(sub.iloc[tr].DOI.map(ndoi));met.append({'fold':f,'n_test':len(te),'test_molecular_groups':g.iloc[te].nunique(),'r2':r2_score(y.iloc[te],z),'mae':mean_absolute_error(y.iloc[te],z),'rmse':mean_squared_error(y.iloc[te],z)**.5,'test_doi_families':len(td),'doi_overlap_with_training':len(td&trd)})
pd.DataFrame(met).to_csv(O/'molecular_grouped_model_metrics.csv',index=False);pd.DataFrame(met)[['fold','test_doi_families','doi_overlap_with_training']].to_csv(O/'source_overlap_audit.csv',index=False)
z=pd.DataFrame(met);report=f'''# 989 arithmetic-matching recovery audit\n\nOf 989 arithmetic-matching records, {len(v)} are `arithmetic_and_source_verified` from preserved Batch021 primary-source mappings. This recovered {len(v)-117} beyond the prior 117 locally verified records; it does not infer evidence from arithmetic alone.\n\nThe 651 not retained earlier divide into: {(m.recovery_classification=='arithmetic_consistent_source_metadata_missing').sum()} metadata-missing/no contradiction, {(m.recovery_classification=='arithmetic_consistent_measurement_basis_unverified').sum()} measurement-basis-unverified, {(m.recovery_classification=='arithmetic_consistent_pairing_ambiguous').sum()} pairing-ambiguous, and {(m.recovery_classification=='arithmetic_consistent_source_conflict').sum()} DOI/source-conflict. Missing documentation is not proof of a wrong value.\n\nThe 81 discrepant and 54 non-comparable records remain separate; no corrections were proposed without direct evidence.\n\nThe recovered subset has {len(sub)} observations, {g.nunique()} molecular identities, and {sub.DOI.map(ndoi).nunique()} DOI families. Fixed historical XGBoost molecular-CV mean fold R² is {z.r2.mean():.6f} (SD {z.r2.std(ddof=1):.6f}); mean MAE {z.mae.mean():.6f}; mean RMSE {z.rmse.mean():.6f}. This is not directly comparable to 0.4004 because the dataset target/data provenance are now explicitly constrained, even though the historical feature schema and fixed parameters were used. DOI overlap occurs in every molecular fold; see the source-overlap audit.\n''';(O/'989_recovery_audit_report.md').write_text(report);(O/'professor_summary.md').write_text(report);(O/'README.md').write_text('Run `python run_989_recovery_audit.py`; it reads preserved Stage A files and writes only this directory.\n')
